-- Synthetic-only privacy lifecycle. Auth deletion completion is simulated in this rolled-back fixture.
create function pg_temp.actor(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub','00000000-0000-4000-8000-'||lpad(n::text,12,'0'),'session_id','10000000-0000-4000-8000-'||lpad(n::text,12,'0'),'aal','aal1')::text,true)::text::void$$;
create function pg_temp.privacy(p jsonb) returns jsonb language sql as $$select public.privacy_command(jsonb_build_object('key',gen_random_uuid())||p)$$;
create function pg_temp.reject_privacy(p jsonb,expected text) returns void language plpgsql as $$begin
 begin perform pg_temp.privacy(p);raise exception 'TEST FAILED: accepted %',p->>'action';exception when others then if sqlerrm<>expected then raise;end if;end;
end$$;
set local role authenticated;
select pg_temp.actor(3);
select pg_temp.assert_true(public.privacy_command('{"action":"read"}')->'request'='null','no invented deletion');
select pg_temp.reject_privacy('{"action":"policy","organization":"20000000-0000-4000-8000-000000000001","revision":0,"recordDays":10,"auditDays":10,"basis":"Synthetic retention basis","notice":"Synthetic retention notice","reviewed":true}','FORBIDDEN');
select pg_temp.privacy(jsonb_build_object('action','request','request','98000000-0000-4000-8000-000000000001','secret',repeat('a',64),'key','99000000-0000-4000-8000-000000000001'));
select pg_temp.assert_true((pg_temp.privacy(jsonb_build_object('action','request','request','98000000-0000-4000-8000-000000000001','secret',repeat('a',64),'key','99000000-0000-4000-8000-000000000001'))->'request'->>'revision')='1','same input replay');
select pg_temp.reject_privacy(jsonb_build_object('action','request','request','98000000-0000-4000-8000-000000000001','secret',repeat('b',64),'key','99000000-0000-4000-8000-000000000001'),'COMMAND_CONFLICT');
select pg_temp.reject_privacy('{"action":"prepare","request":"98000000-0000-4000-8000-000000000001","revision":1,"confirmation":"DELETE MY ACCOUNT","secret":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','REVIEW_REQUIRED');
select pg_temp.actor(4);
select pg_temp.reject_privacy('{"action":"cancel","request":"98000000-0000-4000-8000-000000000001","revision":1}','FORBIDDEN');
select pg_temp.actor(2);
select pg_temp.reject_privacy('{"action":"approve","organization":"20000000-0000-4000-8000-000000000001","request":"98000000-0000-4000-8000-000000000001","revision":1,"policyVersion":1}','FORBIDDEN');
select pg_temp.actor(1);
select pg_temp.privacy('{"action":"policy","organization":"20000000-0000-4000-8000-000000000001","revision":0,"recordDays":10,"auditDays":20,"basis":"Synthetic retention basis only","notice":"Synthetic retained records notice","reviewed":true}');
select pg_temp.reject_privacy('{"action":"policy","organization":"20000000-0000-4000-8000-000000000001","revision":0,"recordDays":10,"auditDays":20,"basis":"Synthetic retention basis only","notice":"Synthetic retained records notice","reviewed":true}','STALE_REVISION');
select pg_temp.privacy('{"action":"hold","organization":"20000000-0000-4000-8000-000000000001","hold":"97000000-0000-4000-8000-000000000001","reason":"Synthetic legal hold reason","reviewOn":"2020-01-01"}');
select pg_temp.reject_privacy('{"action":"approve","organization":"20000000-0000-4000-8000-000000000001","request":"98000000-0000-4000-8000-000000000001","revision":1,"policyVersion":1}','LEGAL_HOLD');
select pg_temp.privacy('{"action":"release","organization":"20000000-0000-4000-8000-000000000001","hold":"97000000-0000-4000-8000-000000000001","reason":"Synthetic reviewed release reason"}');
select pg_temp.privacy('{"action":"approve","organization":"20000000-0000-4000-8000-000000000001","request":"98000000-0000-4000-8000-000000000001","revision":1,"policyVersion":1}');
-- A new policy invalidates earlier approval without altering its history.
select pg_temp.privacy('{"action":"policy","organization":"20000000-0000-4000-8000-000000000001","revision":1,"recordDays":11,"auditDays":21,"basis":"Synthetic updated retention basis","notice":"Synthetic updated retention notice","reviewed":true}');
select pg_temp.actor(3);
select pg_temp.reject_privacy('{"action":"prepare","request":"98000000-0000-4000-8000-000000000001","revision":1,"confirmation":"DELETE MY ACCOUNT","secret":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','REVIEW_REQUIRED');
select pg_temp.actor(1);
select pg_temp.privacy('{"action":"approve","organization":"20000000-0000-4000-8000-000000000001","request":"98000000-0000-4000-8000-000000000001","revision":1,"policyVersion":2}');
-- Sole owner may request, but cannot confirm deletion.
select pg_temp.privacy(jsonb_build_object('action','request','request','98000000-0000-4000-8000-000000000002','secret',repeat('b',64)));
select pg_temp.reject_privacy('{"action":"prepare","request":"98000000-0000-4000-8000-000000000002","revision":1,"confirmation":"DELETE MY ACCOUNT","secret":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"}','SOLE_OWNER');
select pg_temp.privacy('{"action":"cancel","request":"98000000-0000-4000-8000-000000000002","revision":1}');
reset role;
update auth.sessions set created_at=now()-interval '16 minutes' where user_id='00000000-0000-4000-8000-000000000003';
set local role authenticated;
select pg_temp.actor(3);
select pg_temp.reject_privacy('{"action":"prepare","request":"98000000-0000-4000-8000-000000000001","revision":1,"confirmation":"DELETE MY ACCOUNT","secret":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','REAUTHENTICATION_REQUIRED');
reset role;
update auth.sessions set created_at=now() where user_id='00000000-0000-4000-8000-000000000003';
set local role authenticated;
select pg_temp.actor(3);
select pg_temp.privacy('{"action":"prepare","key":"99000000-0000-4000-8000-000000000002","request":"98000000-0000-4000-8000-000000000001","revision":1,"confirmation":"DELETE MY ACCOUNT","secret":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}');
select pg_temp.assert_true((public.privacy_command('{"action":"read"}')->'request'->>'status')='processing','own narrow recovery stays readable');
select pg_temp.assert_true((public.privacy_command('{"action":"prepare","key":"99000000-0000-4000-8000-000000000002","request":"98000000-0000-4000-8000-000000000001","revision":1,"confirmation":"DELETE MY ACCOUNT","secret":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}')->'request'->>'revision')='2','lost prepare response replays exact result');
reset role;
select pg_temp.assert_true(not private.live_identity(false),'old JWT cannot retain business access before provider deletion');
select pg_temp.assert_true(exists(select 1 from public.customer_access where user_id='00000000-0000-4000-8000-000000000003' and revoked_at is not null),'customer access revoked');
select pg_temp.assert_true((select count(*) from public.customers)=3,'company records preserved');
do $$begin begin update public.customer_access set revoked_at=null where user_id='00000000-0000-4000-8000-000000000003';raise exception 'TEST FAILED regrant';exception when others then if sqlerrm<>'ACCOUNT_DELETING' then raise;end if;end;end$$;
set local role service_role;
select pg_temp.assert_true(public.deletion_recovery('98000000-0000-4000-8000-000000000001',repeat('a',64))->>'status'='processing','receipt status no session required');
select pg_temp.assert_true(not(public.deletion_recovery('98000000-0000-4000-8000-000000000001',repeat('a',64))?'user'),'status never exposes target');
select pg_temp.assert_true(public.deletion_recovery('98000000-0000-4000-8000-000000000001',repeat('a',64),false,'96000000-0000-4000-8000-000000000001')->>'user'='00000000-0000-4000-8000-000000000003','leased server recovery binds original target');
select pg_temp.assert_true(public.deletion_recovery('98000000-0000-4000-8000-000000000001',repeat('a',64),false,'96000000-0000-4000-8000-000000000002')->>'busy'='true','second provider attempt cannot acquire active lease');
do $$begin
 begin perform public.deletion_recovery('98000000-0000-4000-8000-000000000001',repeat('b',64));raise exception 'TEST FAILED receipt secret';exception when insufficient_privilege then null;end;
 begin perform public.deletion_recovery('98000000-0000-4000-8000-000000000001',repeat('a',64),true,'96000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED premature completion';exception when others then if sqlerrm<>'PROVIDER_NOT_CONFIRMED' then raise;end if;end;
end$$;
reset role;
update auth.users set deleted_at=now() where id='00000000-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.assert_true(public.deletion_recovery('98000000-0000-4000-8000-000000000001',repeat('a',64),true,'96000000-0000-4000-8000-000000000001')->>'status'='completed','provider deletion must be confirmed in database');
reset role;
set local role authenticated;
select pg_temp.actor(1);
select pg_temp.privacy(jsonb_build_object('action','retain','organization','20000000-0000-4000-8000-000000000001','request','98000000-0000-4000-8000-000000000001','revision',0,'reason','Synthetic reviewed evidence retention','reviewOn',(current_date+30)::text));
select pg_temp.reject_privacy(jsonb_build_object('action','retain','organization','20000000-0000-4000-8000-000000000001','request','98000000-0000-4000-8000-000000000001','revision',0,'reason','Synthetic stale retention review','reviewOn',(current_date+60)::text),'STALE_REVISION');
select pg_temp.assert_true((public.privacy_command('{"action":"read","organization":"20000000-0000-4000-8000-000000000001"}')->'queue'->0->>'retentionRevision')='1','retention review is versioned');
reset role;
select pg_temp.assert_true((select count(*) from private.retention_events where action='identity_deleted')=1,'completion audit appended once');
select pg_temp.assert_true((select count(*) from private.deletion_reviews)=2,'policy review history retained');
select pg_temp.assert_true(not has_function_privilege('anon','public.privacy_command(jsonb)','execute'),'anon cannot call privacy command');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.deletion_recovery(uuid,text,boolean,uuid)','execute'),'browser cannot get deletion target or complete provider result');
select pg_temp.assert_true(not has_table_privilege('authenticated','private.account_deletions','select'),'no direct request table access');
rollback;
